var n=`0959-miso-soup`;var s=`world-0959`;var t=`JP`;var a=`east-asia`;var o=4;var m=27;var g={en:`Miso Soup`,ua:`Місо-суп`};var r={en:`Miso Soup is a Japan dish made with kombu, miso paste (white), tofu (silken), wakame. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Місо-суп, страва кухні країни Японія. Основні складники: комбу, біле місо, шовковий тофу, вакаме. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 13 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 13 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:13,i:[[`dashi-stock`,1e3,`ml`],[`kombu`,14,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`miso-paste-white`,110,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 5 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 5 хвилин до готовності й м’якості.`,t:[`poaching`],m:5,i:[[`tofu-silken`,250,`g`],[`wakame`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,55,`g`]]}];var d={slug:n,id:s,country:`JP`,region:a,servings:4,minutes:27,title:g,text:r,steps:u};export{t as country,d as default,s as id,m as minutes,a as region,o as servings,n as slug,u as steps,r as text,g as title};